import maya.cmds as cmds
import maya.mel as mel


scene_path = "Karen_M_M_full_rig.mb"
path_to_asset = "Input/baked_new_topology.obj"

def open_scene():
    cmds.file(new=True, force=True)
    cmds.file(scene_path, open=True)

def load_plugins():

    # cmds.loadPlugin("fbxmaya")
    # cmds.loadPlugin("gameFbxExporter")
    # #its needed to manually place those in MAYA_PLUG_IN_PATH
    # cmds.loadPlugin("embeddedRL4")
    # cmds.loadPlugin("MayaUE4RBFPlugin2022")
    # cmds.loadPlugin("MayaUERBFPlugin")
    cmds.loadPlugin(allPlugins = True)

def import_persona_mesh():
    cmds.file(path_to_asset, i=True, ignoreVersion=True, type="OBJ", namespace="baked_new_topology", pr=True, importFrameRate=True,importTimeRange="override")

def init_movement():
    cmds.select(cl=True)
    cmds.select('baked_new_topology:Mesh', r=True)
    cmds.move(0, 0, 161.35, r = True)
    cmds.rotate( 90, 0, 0, r = True, os = True, fo = True)
    cmds.move(0, -6, 0, r = True)
    cmds.rotate( 3.6, 0, 0, r = True, os = True, fo = True)
    cmds.select(cl=True)


#TODO: Rest of the operations


def rig_connection():
    cmds.select('baked_new_topology:Mesh', r=True)
    import maya.api.OpenMaya as om
    execfile('D:\\persona-3d\\metahuman_rig_transfer-python-2\\combined_MH.py')
    execfile(os.path.join( os.path.dirname(sys.argv[0]),'metahuman_rig_transfer-python-2','combined_MH.py'))
    cmds.select('DHIhead:spine_04', r=True)
    cmds.select('baked_new_topology:Mesh', add=True)
    #mel.eval('SmoothBindSkin')
    cmds.bindSkin()
    cmds.select('head_lod0_mesh', r=True)
    cmds.select('baked_new_topology:Mesh', add=True)
    cmds.copySkinWeights(noMirror=True, surfaceAssociation='closestPoint', uvSpace=['map1, uv'], influenceAssociation='closestJoint')
    cmds.copySkinWeights(noMirror=True, surfaceAssociation='closestPoint', uvSpace=['map1, uv'], influenceAssociation='oneToOne')

    cmds.select(cl=True)
    #normalize missing influenceAssociation='oneToOne'

def teeth_eyes_fitting():
    cmds.select('teeth_lod0_mesh')
    cmds.move(0, 0.4, 0, r = True)
    cmds.select(cl=True)


